import {flatten,suggestLocal,summarize,validatePlan,exportHTML,parseHTML,escapeHTML as esc,demoRows,sanitizeForAI} from './core.js';
import {buildPrompt,importAIPlan,generateAI} from './ai.js';
import {applyPlan,undoPlan,fingerprint} from './bookmarks.js';
const $=id=>document.getElementById(id),extension=Boolean(globalThis.chrome?.bookmarks);let rows=[],plan=[],isDemo=false,sourceRoot=null,expected='',archiveParent=null,page=0,reviewOnly=false,sourceVersion=0,generationController=null;
const storage=extension?{get:async()=>(await chrome.storage.local.get('recovery')).recovery,set:async v=>chrome.storage.local.set({recovery:v}),clear:async()=>chrome.storage.local.remove('recovery')}:null;
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function download(name,text,type='text/html'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setRows(next,name,demo=false){sourceVersion++;generationController?.abort();generationController=null;if(!next.length)throw Error('没有找到书签，请选择 Chrome 导出的 HTML 文件');if(next.length>10000)throw Error('首版支持一次最多10,000条，请按目录分批导入');if(new Set(next.map(r=>r.id)).size!==next.length)throw Error('输入包含重复ID');rows=next;plan=[];isDemo=demo;page=0;$('sourceName').textContent=name;$('generate').disabled=false;$('results').hidden=true;$('actions').hidden=true;$('statCount').textContent=rows.length;$('statFolders').textContent=new Set(rows.flatMap(r=>r.path.map((_,i)=>r.path.slice(0,i+1).join('/')))).size+' → —';$('statReview').textContent='—';$('statDuplicates').textContent=rows.length-new Set(rows.map(r=>r.url)).size;status(`已读取 ${rows.length} 条书签。${rows.length-sanitizeForAI(rows).length} 条私人、内部或含敏感参数的链接将仅在本地处理。`);}
function parseJSON(text){const d=JSON.parse(text);if(Array.isArray(d)&&d.every(r=>r.url))return d.map((r,i)=>({...r,id:String(r.id||`json-${i}`),title:r.title||r.name||r.url,path:Array.isArray(r.path)?r.path:[]}));if(d.roots)return Object.values(d.roots).flatMap(r=>flatten(r));if(d.children)return flatten(d);throw Error('JSON格式不支持，请使用HTML书签导出文件');}
$('file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;sourceRoot=null;expected='';const text=await f.text();setRows(/\.json$/i.test(f.name)?parseJSON(text):parseHTML(text),f.name);if(extension)$('apply').hidden=true;}catch(e){status(e.message,true);}finally{e.target.value='';}});
$('demo').onclick=()=>{sourceRoot=null;setRows(structuredClone(demoRows),'示例 · 24 条虚构书签',true);plan=suggestLocal(rows);render();status('这是本地规则生成的示例，不是模型结果。你可以修改分类，再导出体验。');$('stats').scrollIntoView({behavior:'smooth',block:'center'});};
$('method').onchange=()=>{$('apiSettings').hidden=$('method').value!=='ai';$('promptPanel').hidden=$('method').value!=='prompt';};
function render(){validatePlan(rows,plan);const s=summarize(rows,plan);$('statCount').textContent=s.count;$('statFolders').textContent=`${s.before} → ${s.after}`;$('statReview').textContent=s.review;$('statDuplicates').textContent=s.duplicates;$('results').hidden=false;$('actions').hidden=false;$('apply').hidden=!extension||!sourceRoot||isDemo;const counts=new Map();for(const p of plan)counts.set(p.destination[0],(counts.get(p.destination[0])||0)+1);$('categories').innerHTML=[...counts].map(([name,n])=>`<div class="category">${esc(name)}<b>${n}</b></div>`).join('');$('destinations').innerHTML=[...new Set(plan.map(p=>p.destination.join('/')))].map(s=>`<option value="${esc(s)}"></option>`).join('');renderRows();}
function renderRows(){const q=$('search').value.toLowerCase(),rowMap=new Map(rows.map(r=>[r.id,r]));const list=plan.filter(p=>{const r=rowMap.get(p.id);return (!reviewOnly||p.confidence==='low')&&`${r.title} ${r.url} ${p.destination.join('/')}`.toLowerCase().includes(q);});page=Math.max(0,Math.min(page,Math.ceil(list.length/20)-1));$('bookmarkList').innerHTML=list.slice(page*20,page*20+20).map(p=>{const r=rowMap.get(p.id);let host;try{host=new URL(r.url).hostname;}catch{host='特殊链接';}return `<div class="bookmark-row"><div><div class="title">${esc(r.title)}</div><div class="domain">${esc(host)}</div><div class="original">原位置：${esc(r.path.join(' / ')||'书签栏根目录')}</div></div><div><input list="destinations" data-id="${esc(r.id)}" aria-label="${esc(r.title)}的分类" value="${esc(p.destination.join('/'))}"><button class="confirm-destination button small" data-confirm="${esc(r.id)}" aria-label="确认${esc(r.title)}的分类">确认分类</button><div class="reason"><span class="confidence ${p.confidence==='low'?'low':''}">${p.source==='manual'?'已确认':p.confidence==='low'?'待确认':p.source==='ai'?'AI建议':'本地规则'}</span><span>${esc(p.reason||'')}</span></div></div></div>`;}).join('')||'<div class="empty">没有匹配的书签</div>';$('pageLabel').textContent=`${list.length? page+1:0} / ${Math.ceil(list.length/20)} 页 · ${list.length} 条`;$('prev').disabled=page===0;$('next').disabled=(page+1)*20>=list.length;}
function confirmDestination(input){const p=plan.find(p=>p.id===input.dataset.id),old=structuredClone(p);try{p.destination=input.value.split('/').map(s=>s.trim());p.confidence='high';p.source='manual';p.reason='你已手动确认用途';validatePlan(rows,plan);render();status('分类已修改。可输入“顶层/子分类”创建新目录，最多两层。');}catch(err){Object.assign(p,old);render();status(err.message,true);}}
$('bookmarkList').addEventListener('click',e=>{const button=e.target.closest('button[data-confirm]');if(button)confirmDestination(button.closest('.bookmark-row').querySelector('input[data-id]'));});
$('search').oninput=()=>{page=0;renderRows();};$('prev').onclick=()=>{page--;renderRows();};$('next').onclick=()=>{page++;renderRows();};$('allRows').onclick=()=>{reviewOnly=false;page=0;$('allRows').classList.add('selected');$('reviewRows').classList.remove('selected');renderRows();};$('reviewRows').onclick=()=>{reviewOnly=true;page=0;$('reviewRows').classList.add('selected');$('allRows').classList.remove('selected');renderRows();};
$('generate').onclick=async()=>{try{if(!rows.length)return;const mode=$('method').value;if(mode==='prompt'){$('promptPanel').hidden=false;$('promptText').value=buildPrompt(rows,$('preferences').value,Number($('maxTop').value));status(`提示词已生成：仅包含 ${sanitizeForAI(rows).length} 条适合发送的公开书签。复制前可以查看完整内容。`);return;}if(mode==='local'){plan=suggestLocal(rows);render();status('本地规则方案已生成，未调用大模型。请确认低置信度条目；需要更贴合个人习惯可选择 AI 深度分类。');return;}
 if(!$('consent').checked)throw Error('请先确认将公开书签信息发送给你选择的模型服务商');const endpoint=$('endpoint').value.trim(),key=$('apiKey').value.trim(),model=$('model').value.trim();const u=new URL(endpoint);if(u.protocol!=='https:')throw Error('模型接口必须为HTTPS');if(!key||!model)throw Error('请填写API Key与模型名称');if(extension){const ok=await chrome.permissions.request({origins:[u.origin+'/*']});if(!ok)throw Error('未授予模型服务商网络权限，未发送数据');}
 $('generate').disabled=true;const revision=sourceVersion,requestRows=rows;generationController=new AbortController();const result=await generateAI(requestRows,{endpoint,key,model,preferences:$('preferences').value,maxTop:Number($('maxTop').value),onProgress:text=>{if(revision===sourceVersion)status(text);},signal:generationController.signal});if(revision!==sourceVersion)return;plan=result.plan;const tokens=result.tokens;render();status(`AI深度方案已生成。${tokens?`服务商返回共 ${tokens} tokens；金额按服务商计费。`:''}请审核后导出或应用。`);
 }catch(e){if(e.name==='AbortError')return;status(e.message==='Failed to fetch'?'无法连接模型接口，可能是CORS或网络限制。可使用扩展，或选择复制提示词模式。':e.message,true);}finally{$('generate').disabled=!rows.length;}};
$('copyPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('promptText').value);status('提示词已复制。请粘贴到你自己的AI对话中。');}catch{status('无法自动复制，请选中提示词手动复制。',true);}};
$('importResult').onclick=()=>{try{plan=importAIPlan(rows,$('aiResult').value);render();status('AI返回结果已逐条校验。私人链接使用本地分类，未遗漏任何书签。');}catch(e){status(e.message,true);}};
$('backup').onclick=()=>{download('书签归位-原始备份.html',rawHTML(rows));};
function rawHTML(data){const tree={};for(const r of data){let t=tree;for(const s of r.path){t.children??=new Map();if(!t.children.has(s))t.children.set(s,{});t=t.children.get(s);}t.links??=[];t.links.push(r);}function write(t){let h='';for(const [name,v]of t.children||[])h+=`<DT><H3>${esc(name)}</H3><DL><p>${write(v)}</DL><p>`;for(const r of t.links||[])h+=`<DT><A HREF="${esc(r.url)}"${r.dateAdded?` ADD_DATE="${Math.floor(r.dateAdded/1000)}"`:''}>${esc(r.title)}</A>\n`;return h;}return `<!DOCTYPE NETSCAPE-Bookmark-file-1><META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8"><TITLE>书签备份</TITLE><H1>Bookmarks</H1><DL><p>${write(tree)}</DL><p>`;}
$('export').onclick=()=>{try{download('书签归位-整理结果.html',exportHTML(rows,plan));status('已导出整理结果。Chrome导入会新增目录；核对后再删除旧目录。');}catch(e){status(e.message,true);}};
async function refreshBackup(){if(!extension)return;const s=await storage.get();$('undo').disabled=!s;$('backupState').textContent=s?`有${s.status==='applied'?'可撤销':'未完成'}的整理快照`:'尚无整理快照';}
if(extension){$('modeBadge').textContent='Chrome 扩展 · 直接整理';$('extensionControls').hidden=false;const roots=(await chrome.bookmarks.getTree())[0].children||[];const bars=roots.filter(r=>r.folderType==='bookmarks-bar'&&!r.unmodifiable);archiveParent=roots.find(r=>r.folderType==='other'&&!r.unmodifiable)?.id;if(!bars.length){status('当前浏览器没有可编辑的书签栏，请检查组织管理策略。',true);}else{$('rootSelect').innerHTML=bars.map((r,i)=>`<option value="${esc(r.id)}">${esc(r.title)}${bars.length>1?` · ${r.syncing?'账号同步':'本机'} ${i+1}`:''}</option>`).join('');}await refreshBackup();
 $('readChrome').onclick=async()=>{try{sourceRoot=$('rootSelect').value;const root=(await chrome.bookmarks.getSubTree(sourceRoot))[0];expected=fingerprint(root);setRows(flatten(root),`Chrome · ${root.title}`);}catch(e){status(e.message,true);}};
 $('apply').onclick=async()=>{if(!sourceRoot||isDemo)return;try{validatePlan(rows,plan);if(!archiveParent)throw Error('没有可用的其他书签目录，无法保存旧目录');if(!confirm(`将移动 ${rows.length} 条书签，重建为预览中的目录。原书签不会删除，旧文件夹存入其他书签用于撤销。继续前建议下载原始HTML备份。确认应用？`))return;await chrome.runtime.sendMessage({type:'PAUSE_AUTO'});$('autoEnabled').checked=false;document.querySelector('.workspace').classList.add('busy');status('正在归位，请保持此页面打开…');await applyPlan(chrome.bookmarks,storage,sourceRoot,archiveParent,expected,rows,plan);$('apply').hidden=true;sourceRoot=null;status('书签栏已归位，逐条核验通过。旧空目录已存入“其他书签”的整理备份；可点击撤销恢复。');}catch(e){status(e.message,true);}finally{document.querySelector('.workspace').classList.remove('busy');await refreshBackup();}};
 $('undo').onclick=async()=>{try{if(!confirm('将恢复上次整理前的目录及书签位置，继续？'))return;await chrome.runtime.sendMessage({type:'PAUSE_AUTO'});$('autoEnabled').checked=false;document.querySelector('.workspace').classList.add('busy');await undoPlan(chrome.bookmarks,storage);sourceRoot=null;plan=[];$('results').hidden=true;$('actions').hidden=true;$('generate').disabled=true;status('已恢复原目录与书签位置。重新读取即可再次整理。');}catch(e){status(e.message,true);}finally{document.querySelector('.workspace').classList.remove('busy');await refreshBackup();}};
}
if(extension){
 $('autoPanel').hidden=false;
 async function showAuto(){
  const {autoConfig,autoHistory=[]}=await chrome.storage.local.get(['autoConfig','autoHistory']);
  $('autoEnabled').checked=!!autoConfig?.enabled;
  if(autoConfig?.engine)$('autoEngine').value=autoConfig.engine;
  $('autoHistory').innerHTML=autoHistory.slice(0,5).map(r=>`<div>${esc(r.title||'新书签')} → ${esc(r.error||r.destination?.join(' / ')||'原位置')} · ${esc(r.undone?'已撤销':r.notice||'')} ${r.confidence==='low'?'· 待确认':''}</div>`).join('')||'开启后，最近的自动归类记录会显示在这里。';
  $('undoAuto').disabled=!autoHistory.some(r=>!r.error&&!r.undone);
 }
 await showAuto();
 chrome.storage.onChanged.addListener((changes,area)=>{if(area==='local'&&(changes.autoHistory||changes.autoConfig))showAuto();});
 $('saveAuto').onclick=async()=>{
  try{
   const engine=$('autoEngine').value,enabled=$('autoEnabled').checked;
   if(engine==='ai'&&enabled){
    if(!$('consent').checked)throw Error('请在AI配置中确认向服务商发送信息，再开启自动AI归类');
    const endpoint=$('endpoint').value.trim(),key=$('apiKey').value.trim(),model=$('model').value.trim(),u=new URL(endpoint);
    if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||!key||!model)throw Error('请填写有效的HTTPS接口、模型与API Key');
    if(!confirm('自动AI归类会在每次新增公开书签时，将标题、域名和现有文件夹名称发送给 '+u.hostname+'，可能产生API费用。是否开启？'))return;
    if(!await chrome.permissions.request({origins:[u.origin+'/*']}))throw Error('未授权网络访问');
    await chrome.storage.session.set({autoAI:{endpoint,key,model,preferences:$('preferences').value}});
   }else await chrome.storage.session.remove('autoAI');
   await chrome.storage.local.set({autoConfig:{enabled,engine,rootId:$('rootSelect').value}});
   await chrome.runtime.sendMessage({type:enabled?'RESUME_AUTO':'PAUSE_AUTO'});
   status(enabled?'新收藏自动归类已开启。已有书签不受影响，可在此查看最近记录。':'已关闭新收藏自动归类');
   await showAuto();
  }catch(e){status(e.message,true);}
 };
 $('undoAuto').onclick=async()=>{const r=await chrome.runtime.sendMessage({type:'UNDO_AUTO'});status(r.error||'已将最近自动归类的书签移回原位置',!!r.error);await showAuto();};
}

$('configFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const text=await f.text(),config={};for(const line of text.split(/\r?\n/)){if(!line.trim()||line.trim().startsWith('#'))continue;const i=line.indexOf('=');if(i>0)config[line.slice(0,i).trim()]=line.slice(i+1).trim().replace(/^['"]|['"]$/g,'');}if(!config.API_KEY||!config.BASE_URL||!config.MODEL)throw Error('配置文件必须包含 API_KEY、BASE_URL、MODEL');const u=new URL(config.BASE_URL);if(u.protocol!=='https:')throw Error('BASE_URL必须为HTTPS');$('apiKey').value=config.API_KEY;$('endpoint').value=config.BASE_URL.replace(/\/$/,'')+(u.pathname.replace(/\/$/,'').endsWith('/v1')?'/chat/completions':'/v1/chat/completions');$('model').value=config.MODEL;status('本地配置已载入当前页面内存，密钥不会显示、保存或进入导出文件。');}catch(err){status(err.message,true);}finally{e.target.value='';}};
